// Review and training contracts; frontend types are generated by ts-rs.
enumeration!(DataStatus { Missing, Pending, Partial, Ready, Unsupported, Failed });
enumeration!(MetricStatus { Available, Missing, NotApplicable, Unsupported });
enumeration!(GoalState { Draft, Active, Paused, Completed, Abandoned });
dto!(MatchRef {match_key:String, player_key:String});
dto!(ReviewQuery {match_key:String, player_key:String, input_revision:Option<u32>, report_id:Option<String>});
dto!(InputRef {match_key:String, player_key:String, input_revision:u32});
dto!(Capability {status:DataStatus, from_ms:Option<u32>, to_ms:Option<u32>, reason:Option<String>});
dto!(Participant {id:u32, puuid:Option<String>, team_id:u32, champion_id:Option<u32>, position:Option<String>, kills:Option<u32>, deaths:Option<u32>, assists:Option<u32>, lane_cs:Option<u32>, jungle_cs:Option<u32>, damage:Option<u32>, gold:Option<u32>});
dto!(MatchContext {match_key:String, player_key:String, target_id:u32, participants:Vec<Participant>, team_kills:BTreeMap<String,u32>, queue_id:Option<u32>, map_id:Option<u32>, mode:Option<String>, version:String, duration_ms:u32, started_at:String, remake:bool, source:Source});
dto!(FramePoint {timestamp_ms:u32, participant_id:u32, gold:Option<u32>, xp:Option<u32>, cs:Option<u32>, path:String});
dto!(TimelineEvent {id:String, timestamp_ms:u32, kind:String, participant_id:Option<u32>, killer_id:Option<u32>, victim_id:Option<u32>, assisting_ids:Vec<u32>, item_id:Option<u32>, skill_slot:Option<u32>, monster:Option<String>, undo_of:Option<String>, path:String, raw:serde_json::Value});
dto!(AnalysisInput {id:String, revision:u32, fingerprint:String, converter_version:String, summary_snapshot:String, timeline_snapshot:Option<String>, context:MatchContext, capabilities:BTreeMap<String,Capability>, frames:Vec<FramePoint>, events:Vec<TimelineEvent>, limitations:Vec<String>});
dto!(MetricResult {id:String, version:String, unit:String, value:Option<f64>, denominator:Option<f64>, sampled_at_ms:Option<u32>, status:MetricStatus, reason:Option<String>});
dto!(EvidenceRef {id:String, snapshot_id:String, path:String, timestamp_ms:Option<u32>, participant_ids:Vec<u32>});
dto!(Finding {id:String, rule_id:String, rule_version:String, priority:u32, message_key:String, action_key:Option<String>, params:BTreeMap<String,String>, metric_ids:Vec<String>, evidence_ids:Vec<String>, limitations:Vec<String>});
dto!(ReviewReport {id:String, revision:u32, match_key:String, player_key:String, input_revision:u32, input_fingerprint:String, rule_version:String, semantic_version:Option<String>, metrics:Vec<MetricResult>, findings:Vec<Finding>, evidence:Vec<EvidenceRef>, limitations:Vec<String>, generated_at:String});
dto!(ReviewData {summary:MatchSummary, input:Option<AnalysisInput>, report:Option<ReviewReport>, summary_status:DataStatus, timeline_status:DataStatus, retry_at:Option<String>, last_error:Option<AppError>, active_task:Option<Task>, newer_input:bool, latest_input_revision:Option<u32>});
dto!(GenerateReview {match_key:String, player_key:String, input_revision:u32});
dto!(TimelineQuery {match_key:String, player_key:String, input_revision:u32, from_ms:u32, to_ms:u32, kinds:Vec<String>, cursor:Option<u32>, limit:Option<u32>});
dto!(TimelineSlice {events:Vec<TimelineEvent>, next_cursor:Option<u32>, capabilities:BTreeMap<String,Capability>});
dto!(ChartQuery {match_key:String, player_key:String, input_revision:u32, from_ms:u32, to_ms:u32, max_points:u32});
dto!(ChartPoint {timestamp_ms:u32, gold:Option<f64>, cs:Option<f64>, opponent_gold:Option<f64>, opponent_cs:Option<f64>});
dto!(ChartData {points:Vec<ChartPoint>, limitations:Vec<String>});
dto!(EvidenceQuery {report_id:String, evidence_id:String});
dto!(EvidenceData {reference:EvidenceRef, raw:serde_json::Value});
dto!(ReviewNote {id:String, match_key:String, player_key:String, report_id:Option<String>, evidence_id:Option<String>, text:String, revision:u32, updated_at:String});
dto!(SaveNote {workspace_epoch:String,id:Option<String>, match_key:String, player_key:String, report_id:Option<String>, evidence_id:Option<String>, text:String, expected_revision:u32});
dto!(DeleteNote {workspace_epoch:String,id:String, expected_revision:u32});
dto!(ReviewFeedback {report_id:String, finding_id:String, value:Option<String>, revision:u32, updated_at:String});
dto!(SaveFeedback {workspace_epoch:String,report_id:String, finding_id:String, value:Option<String>, expected_revision:u32});
dto!(AnnotationsQuery {match_key:String, player_key:String, report_id:Option<String>});
dto!(ReviewAnnotations {notes:Vec<ReviewNote>, feedback:Vec<ReviewFeedback>});
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all="camelCase", deny_unknown_fields)]
pub struct GoalScope {
 pub player_key:String, pub queue_id:u32, pub position:String, pub patch:String,
 #[serde(default)] #[ts(optional)] pub champion_id:Option<u32>,
 pub metric_id:String, pub metric_version:String, pub direction:String, pub target:f64,
 #[serde(default)] #[ts(optional)] pub origin:Option<GoalOrigin>,
}
dto!(GoalMember {match_key:String, report_id:String, input_fingerprint:String, started_at:String, value:f64});
dto!(TrainingGoal {id:String, version:u32, revision:u32, scope:GoalScope, state:GoalState, baseline:Vec<GoalMember>, baseline_excluded:Option<BTreeMap<String,u32>>, created_at:String, window_start:String, previous_goal_id:Option<String>});
dto!(SaveGoal {workspace_epoch:String,id:Option<String>, expected_revision:u32, scope:GoalScope, state:GoalState});
dto!(GoalQuery {player_key:String, state:Option<GoalState>, cursor:Option<u32>, limit:Option<u32>});
dto!(GoalPage {items:Vec<TrainingGoal>, next_cursor:Option<u32>});
dto!(GoalProgressQuery {goal_id:String, revision:Option<u32>});
dto!(GoalEvaluation {id:String, goal_id:String, revision:u32, algorithm_version:String, baseline:Option<f64>, current:Option<f64>, delta:Option<f64>, target:f64, achieved:Option<bool>, members:Vec<GoalMember>, excluded:BTreeMap<String,u32>, window_start:String, window_end:Option<String>, generated_at:String});
dto!(GoalAvailability {scanned:u32, truncated:bool, missing_details:Vec<MatchRef>, missing_reports:Vec<MatchRef>, not_applicable:u32, version_mismatch:u32});
dto!(GoalProgress {goal:TrainingGoal, evaluation:Option<GoalEvaluation>, frozen_baseline:Option<f64>, availability:GoalAvailability});
dto!(PlayerProgressQuery {player_key:String, queue_id:Option<u32>, position:Option<String>, patch:Option<String>, from:Option<String>, to:Option<String>});
dto!(TrendPoint {match_key:String, report_id:String, started_at:String, group:String, metrics:Vec<MetricResult>});
dto!(PlayerProgress {points:Vec<TrendPoint>, excluded:BTreeMap<String,u32>, cached_matches:u32, from:Option<String>, to:Option<String>});
